use std::fs

struct Tree {
    key: Vec<int>,
    l: Vec<int>,
    r: Vec<int>,
    root: int,
    found: bool,
}

impl Tree {
    fn has(self, x: int) -> bool {
        let mut n = self.root
        while n != -1 {
            let k = self.key[n as usize]
            if x == k { return true }
            if x < k { n = self.l[n as usize] } else { n = self.r[n as usize] }
        }
        false
    }

    fn add(self, x: int) {
        let id = self.key.len() as int
        self.key.push(x)
        self.l.push(-1)
        self.r.push(-1)
        if self.root == -1 {
            self.root = id
            return
        }
        let mut n = self.root
        loop {
            let k = self.key[n as usize]
            if x < k {
                if self.l[n as usize] == -1 {
                    self.l[n as usize] = id
                    return
                }
                n = self.l[n as usize]
            } else {
                if self.r[n as usize] == -1 {
                    self.r[n as usize] = id
                    return
                }
                n = self.r[n as usize]
            }
        }
    }

    fn del(self, n: int, x: int) -> int {
        if n == -1 { return -1 }
        let k = self.key[n as usize]
        if x < k {
            let c = self.del(self.l[n as usize], x)
            self.l[n as usize] = c
            return n
        }
        if x > k {
            let c = self.del(self.r[n as usize], x)
            self.r[n as usize] = c
            return n
        }
        self.found = true
        if self.l[n as usize] == -1 { return self.r[n as usize] }
        if self.r[n as usize] == -1 { return self.l[n as usize] }
        let mut s = self.r[n as usize]
        while self.l[s as usize] != -1 { s = self.l[s as usize] }
        let sk = self.key[s as usize]
        self.key[n as usize] = sk
        let c = self.del(self.r[n as usize], sk)
        self.r[n as usize] = c
        n
    }

    fn height(self, n: int) -> int {
        if n == -1 { return 0 }
        let a = self.height(self.l[n as usize])
        let b = self.height(self.r[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, n: int, out: Vec<string>) -> Vec<string> {
        if n == -1 { return out }
        let mut o = self.walk(self.l[n as usize], out)
        o.push("${self.key[n as usize]}")
        self.walk(self.r[n as usize], o)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { key: [], l: [], r: [], root: -1, found: false }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.has(x) { println("dup") } else {
                t.add(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.has(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            t.found = false
            let r = t.del(t.root, x)
            t.root = r
            if t.found { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            if t.root == -1 { println("<empty>") } else {
                let o = t.walk(t.root, [])
                println(o.join(" "))
            }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root == -1 { println("empty") } else {
                let mut n = t.root
                while t.l[n as usize] != -1 { n = t.l[n as usize] }
                println("${t.key[n as usize]}")
            }
        } else if cmd == "max" {
            if t.root == -1 { println("empty") } else {
                let mut n = t.root
                while t.r[n as usize] != -1 { n = t.r[n as usize] }
                println("${t.key[n as usize]}")
            }
        }
    }
}

